/// Maximum chars of a tool result stored in memory (~5k tokens). Tool outputs
/// longer than this are truncated (with a notice) so a single read_file of a
/// huge file can't blow out the context window for the rest of the run.
fn max_tool_result_chars() -> u32 {
    return 20000;
}

pub fn truncate_tool_result(s: &str) -> String {
    let cap = max_tool_result_chars();
    let count: u32 = ((s.len() as i64) as u32);
    if count <= cap {
        return s.to_string();
    }
    let kept = &s[0 as usize..cap as usize];
    let dropped: u32 = count - cap;
    return format!("{}
…[truncated {} more chars]", kept, dropped);
}

