/// (Plan 016 2.2 + Plan 022 Phase 3.1 — previously only cached the block,
/// leaving skill(...) tool calls as "tool not found".)
/// Snapshot of the current conversation memory (for session persistence).
/// Current conversation memory.
/// Run the ReAct loop against `task`, returning the agent's final answer.
/// Non-streaming, non-cancellable (delegates to run_inner with cancel=None
/// and a throwaway EventSink that consumes the events — nothing observable).
/// `mut fn`: the loop mutates self.memory/tools.
/// Queue a steering message (Plan 026): injected into the conversation
/// after the current tool batch completes, before the next LLM call —
/// never interrupts an in-flight tool. Safe to call mid-run.
/// Queue a follow-up message (Plan 026): revives the run when it was about
/// to end naturally (final answer, no pending tools); counted against the
/// turn limits (anti-runaway).
/// Shared handle to the steering queue (app-layer wiring, e.g. musk's
/// axum handlers pushing directly mid-run).
/// Shared handle to the follow-up queue.
/// Plan 026: cancel drops queued steering messages; report the loss so the
/// UI can tell the user their mid-run messages were discarded.
/// Like run, but honors a cancellation flag at the turn boundaries AND
/// streams every ReAct event to `sink` (Plan 021 缺口 1). The Rust original
/// takes an `Arc<dyn Fn(StreamEvent)>` callback; the Auto port takes a
/// `TaskRef<StreamEvent>` actor handle instead (auto-lang Plan 387 §16/17 —
/// the EventSink task is defined above). The caller spawns the sink with a
/// forwarding closure (Plan 390 §15.10 Box<dyn Fn>):
/// `Task.spawn("EventSink", 16, f"", Box((ev) => forward(ev, on_event)))`.
/// `mut fn`: run_inner mutates self.memory/tools.
/// Override the compaction settings (Plan 028). Plan 031: an explicit
/// override also pins context_window — later response metadata no longer
/// adjusts it.
/// The current compaction settings (Plan 031: the window may have been
/// refreshed from response metadata — tests assert on the live value).
/// Compact now and report via a Warning (Plan 031: shared by the pre-run
/// threshold check and the overflow-recovery path). Updates last_summary
/// so the next compaction can use the incremental UPDATE template.
/// Returns false when compaction failed (caller keeps the original memory).
/// Issue this turn's LLM request with overflow recovery (Plan 031): when
/// the call fails with a context-overflow error — either as a transport
/// error or in-band as resp.error — compact the memory and retry this
/// turn's request ONCE against the compacted history (bounded, no loop).
/// A second overflow propagates as an error.
/// Unified ReAct loop backing run + run_stream.
/// 
/// Each turn: build a request from memory + role, ask the model, execute
/// any tool calls, feed results back. Stops when the model replies with
/// plain text (no tool calls), a tool-call cycle is detected
/// (LOOP_DETECT_THRESHOLD), or the hard safety cap (max_turns * 5) is hit.
/// The Role's max_turns is a SOFT target — the agent may exceed it while
/// still making progress; the hard cap is 5x the soft target.
/// `mut fn`: mutates self.memory (add/add_message) + self.tools.
/// Build the completion request for the current turn: system prompt from
/// the Role, the role's tier/model, the full memory, and the tools the
/// Role allows.
/// True when the caller has requested cancellation (cancel flag set + true).
fn is_cancelled(cancel: Option<Arc<AtomicBool>>) -> bool {
    match cancel {
        None => return false,
        Some(c) => {
            

            let v = c.load(Ordering::SeqCst);
            return v;
        },
    }
}

/// Increment the recurrence count for a (tool, args) key, returning the new
/// count. Keeps the parallel `seen_names` key list in sync (Auto's VM Map has
/// no iteration API — plan 013 gotcha B5).
fn bump_seen(mut seen: std::collections::HashMap<String, u32>, mut seen_names: Vec<String>, key: &str) -> u32 {
    let mut prev: u32 = 0 as u32;


    match seen.get(key) {
        Some(n) => prev = n.clone(),
        None => seen_names.push(key.to_string()),
    };
    let next: u32 = prev + 1;
    seen.insert(key.to_string(), next);
    return next;
}

/// Compute the updated running token total after folding in a response's usage
/// (if any). Returned so the caller assigns it back — a2r clones struct args at
/// call sites, so mutating a `result` param in place wouldn't reach the caller,
/// and the param binding isn't `mut` by default (E0594).
fn record_usage(result: AgentResult, resp: CompletionResponse) -> u32 {
    match resp.usage {
        Some(u) => return result.total_tokens + u.total_tokens(),
        None => return result.total_tokens,
    }
}

/// A Cancelled event carrying a snapshot of the current result.
fn cancelled_event(mut result: AgentResult) -> StreamEvent {
    return StreamEvent::Cancelled(clone_result(result.clone()));
}

/// Forward one SSE event (from Client.complete_stream's callback) to the
/// EventSink. Reasoning-aware (Plan 026): a `{"type":"reasoning","text":…}`
/// chunk forwards as StreamEvent.Thinking, everything else with text as
/// StreamEvent.Delta — matching rust-ref agent.rs (the .at track previously
/// degraded all text to Delta; Plan 022 §6.1 conservative increment retired).
/// Extracted as a free fn so the run_inner closure stays a single-expression
/// arrow closure (a2r parses `(ev) => expr`, not block-body move closures).
/// `@TaskRef` (by ref): TaskRef is not Clone; send takes &self, so a borrow
/// suffices and avoids a2r's move-reuse clone inference (Plan 019 class D).
fn forward_sse_delta(mut ev: JsonValue, sink: &a2r_std::task::TaskRef<StreamEvent>) {
    let mut ty: String = "".to_string();
    match ev.get("type") {
        Some(t) => ty = t.as_str().unwrap_or_default().to_string(),
        None => {},
    };
    match ev.get("text") {
        Some(t) => {
            let text = t.as_str().unwrap_or_default();
            if text.is_empty() == false {
                if ty == "reasoning" {
                    sink.send(StreamEvent::Thinking(text.to_string()));
                } else {
                    sink.send(StreamEvent::Delta(text.to_string()));
                }
            }
        },
        None => {},
    };
}

/// Pop the front element of a shared string queue (Plan 026 steering /
/// follow-up), or None when empty. The guard is released when this fn returns,
/// so callers can safely mutate agent memory right after.
fn pop_front(q: Arc<Mutex<Vec<String>>>) -> Option<String> {
    let mut guard = q.lock();
    if (guard.len() as i64) > 0 {
        let msg = guard.remove(0);
        return Some(msg);
    }
    return None;
}

/// Copy an AgentResult (used for event payloads, so the returned result stays
/// independent of the running accumulator).
fn clone_result(result: AgentResult) -> AgentResult {
    return AgentResult { output: result.output.to_string(), turns: result.turns, tool_calls: result.tool_calls.clone(), total_tokens: result.total_tokens };
}

/// Build the model id: a pinned id if set, else a "tier:<tier>" token.
fn build_model_id(pinned: &str, mut tier: ModelTier) -> String {
    if pinned.is_empty() == false {
        return pinned.to_string();
    }
    return format!("tier:{}", tier.display_name());
}

/// Assemble the system prompt: optional project context + role soul + optional
/// skills directory block.
fn build_system_prompt(context_block: Option<String>, soul: &str, skills_block: Option<String>) -> String {
    let mut prompt: String = "".to_string();
    match context_block {
        Some(ctx) => {
            if ctx.trim().to_string().is_empty() == false {
                prompt = format!("{}{}", ctx, "\n\n---\n\n");
            }
        },
        None => {},
    };
    prompt = format!("{}{}", prompt, soul);
    match skills_block {
        Some(block) => prompt = format!("{}{}", prompt, block),
        None => {},
    };
    return prompt;
}
